/**
 * One-time data migration: strip the random suffix off auto-generated usernames.
 *
 * MNNIT institutional emails are `name.regno@mnnit.ac.in`, so the local part is
 * already a unique, human-readable identifier per student. Registration used to
 * always append a random 6-hex-char suffix (e.g. `krishna.20233169_76a463`)
 * regardless of whether the bare name was free — see auth.service.js
 * `generateUniqueUsername`, which now tries the bare name first. This migration
 * retroactively cleans up accounts created before that fix, for users who never
 * customized their username away from the auto-generated default.
 *
 * Detection: a username is treated as untouched-auto-generated only if it is
 * EXACTLY `<sanitized email local part>_<6 hex chars>` — the same shape the old
 * generator produced. A user who deliberately chose a username can't plausibly
 * collide with that exact pattern, so this never touches a real customization.
 *
 * Safety properties:
 *  - `dryRun` reads and reports but writes nothing.
 *  - Idempotent: re-running finds nothing left to migrate.
 *  - Never overwrites another user's username — a collision on the bare target
 *    (e.g. it was already claimed by someone else) is skipped and reported,
 *    never forced.
 */

const AUTO_GEN_SUFFIX = /^[0-9a-f]{6}$/;

const sanitizeBase = (email) => email.split("@")[0].replace(/[^a-zA-Z0-9_.]/g, "_");

export const migrateAutoGeneratedUsernames = async (db, { dryRun = false, log = () => {} } = {}) => {
  const usersCol = db.collection("users");
  const cursor = usersCol.find({}, { projection: { username: 1, email: 1 } });

  const stats = { scanned: 0, migrated: 0, skippedCollision: 0, skippedNotAutoGen: 0, failed: [] };
  const candidates = [];

  while (await cursor.hasNext()) {
    const user = await cursor.next();
    stats.scanned += 1;
    if (!user.email || !user.username) {
      stats.skippedNotAutoGen += 1;
      continue;
    }

    const base = sanitizeBase(user.email);
    const prefix = `${base}_`;
    if (!user.username.startsWith(prefix)) {
      stats.skippedNotAutoGen += 1;
      continue;
    }

    const suffix = user.username.slice(prefix.length);
    if (!AUTO_GEN_SUFFIX.test(suffix)) {
      stats.skippedNotAutoGen += 1;
      continue;
    }

    candidates.push({ id: user._id, from: user.username, to: base });
  }

  for (const candidate of candidates) {
    const existing = await usersCol.findOne({ username: candidate.to });
    if (existing && existing._id.toString() !== candidate.id.toString()) {
      stats.skippedCollision += 1;
      log(`SKIP (collision): ${candidate.from} -> ${candidate.to} already taken by another user`);
      continue;
    }

    log(`${dryRun ? "[DRY RUN] " : ""}${candidate.from} -> ${candidate.to}`);
    if (dryRun) {
      stats.migrated += 1;
      continue;
    }

    try {
      await usersCol.updateOne({ _id: candidate.id }, { $set: { username: candidate.to } });
      stats.migrated += 1;
    } catch (err) {
      stats.failed.push({ id: candidate.id.toString(), from: candidate.from, to: candidate.to, error: err.message });
    }
  }

  return stats;
};
